def mean_absolute_deviation(numbers: List[float]) -> float:
    mean = sum(numbers) / len(numbers)
    return sum(abs(x - mean) for x in numbers) / len(numbers)

def max_value_on_paths(N, grid_values):
    # Initialize the dynamic programming table
    dp = [[0] * N for _ in range(N)]

    # Loop through the grid values and populate the table
    for x, y, value in grid_values:
        dp[y][x] = value

    # Loop through the table and find the maximum sum of values
    # on two paths from the top-left to the bottom-right
    max_sum = 0
    for y in range(N):
        for x in range(N):
            if y == 0 and x == 0:
                continue
            elif y == 0:
                max_sum = max(max_sum, dp[y][x] + dp[y][x-1])
            elif x == 0:
                max_sum = max(max_sum, dp[y][x] + dp[y-1][x])
            else:
                max_sum = max(max_sum, dp[y][x] + max(dp[y][x-1], dp[y-1][x]))

    return max_sum

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.

    Example:
        >>> find_number_combinations()
        [(123, 246, 369), (124, 248, 372), ...]
    """
    combinations = []
    for i in range(1, 10):
        for j in range(i*2, 10):
            for k in range(i*3, 10):
                if i < j < k:
                    combinations.append((i, j, k))
    return sorted(combinations)

def decode(encoded, original, message):
    # Build a mapping from encoded letters to their original letters
    mapping = {}
    for i in range(len(original)):
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        else:
            return "Failed"

    # Use the mapping to decode the message
    decoded = ""
    for letter in message:
        if letter in mapping:
            decoded += mapping[letter]
        else:
            return "Failed"

    return decoded

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n > last:
        return 0
    if n == last:
        return 1
    if n in memo:
        return memo[n]
    count = 0
    for i in range(1, n + 1):
        if i <= last / 2:
            count += count_sequences(i, n, memo)
    memo[n] = count
    return count

def count_coprime_pairs(x0, y0):
    count = 0
    for a in range(1, y0 // x0 + 1):
        b = y0 // a
        if a * b == y0 and gcd(a, b) == 1:
            count += 1 if a == b else 2
    return count

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num == 2 or num == 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def check_scenario(scenario, liar_count, statements, days_of_week):
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Initialize a dictionary to store the number of statements for each participant
    participant_count = {}

    # Iterate over the statements and update the participant count
    for participant, statements in statements.items():
        participant_count[participant] = len(statements)

    # Check if the scenario is consistent with the statements
    for participant, statements in statements.items():
        if participant == scenario:
            # If the participant is the criminal, check if they made any statements
            if len(statements) == 0:
                return False
        else:
            # If the participant is not the criminal, check if they made any statements
            if len(statements) > 0:
                return False

    # Check if any liars made any statements
    for liar in liar_count:
        if len(statements[liar]) > 0:
            return False

    # If all checks pass, the scenario is consistent with the statements
    return True

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    return sum(catalan_number(i) * catalan_number(n - i - 1) for i in range(n))

