def remaining_trees_after_clearing(l, areas):
    remaining_trees = l
    for start, end in areas:
        remaining_trees -= min(remaining_trees, end - start + 1)
    return remaining_trees

def min_remaining_space(V, n, volumes):
    # Initialize a two-dimensional array to store the maximum occupied volume for each subset of items
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Initialize the base case: the maximum occupied volume for a single item is its own volume
    for i in range(1, n + 1):
        dp[i][i] = volumes[i - 1]

    # Fill in the rest of the array using the dynamic programming approach
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    # Return the difference between the box's total capacity and the maximum occupied volume
    return V - max(dp[1][n], 0)

def total_smoked_cigarettes(n, k):
    total = 0
    while n >= k:
        total += n // k
        n = n // k + (n % k)
    return total + n
